import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

/**
 * figma: InputGroup (State = Default | Focus | Destructive, Roudness, Dir),
 * InputGroupAddon (Dir) and InputGroupControl (Dir).
 *
 * The group owns the border, radius and focus ring; the inner control is
 * borderless and transparent so addons sit flush inside the same box.
 */
const inputGroupVariants = cva(
  cn(
    "group/input-group relative flex w-full items-center gap-2 border border-input bg-background",
    "px-2.5 shadow-xs transition-[color,box-shadow] outline-none",
    "has-[>[data-slot=input-group-control]:focus-visible]:border-ring",
    "has-[>[data-slot=input-group-control]:focus-visible]:ring-ring-subtle",
    "has-[>[data-slot=input-group-control]:focus-visible]:ring-[3px]",
    "has-[>[data-slot=input-group-control][aria-invalid=true]]:border-destructive",
    "has-[>[data-slot=input-group-control][aria-invalid=true]]:ring-ring-destructive",
    "has-[>[data-slot=input-group-control][aria-invalid=true]]:ring-[3px]",
    "has-[>[data-slot=input-group-control]:disabled]:pointer-events-none",
    "has-[>[data-slot=input-group-control]:disabled]:bg-input/50",
    "rounded-lg"
  ),
  {
    variants: {
      size: { default: "h-8", lg: "h-9", block: "h-auto flex-col items-stretch py-2" },
    },
    defaultVariants: { size: "default" },
  }
);

function InputGroup({
  className,
  size,
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof inputGroupVariants>) {
  return (
    <div
      role="group"
      data-slot="input-group"
      className={cn(inputGroupVariants({ size }), className)}
      {...props}
    />
  );
}

function InputGroupAddon({
  className,
  align = "inline-start",
  ...props
}: React.ComponentProps<"div"> & {
  align?: "inline-start" | "inline-end" | "block-start" | "block-end";
}) {
  return (
    <div
      data-slot="input-group-addon"
      data-align={align}
      className={cn(
        "flex shrink-0 items-center gap-1.5 text-sm text-muted-foreground select-none",
        "[&_svg:not([class*='size-'])]:size-4 [&_svg]:pointer-events-none",
        align === "block-start" || align === "block-end" ? "w-full" : "",
        className
      )}
      {...props}
    />
  );
}

function InputGroupControl({ className, ...props }: React.ComponentProps<"input">) {
  return (
    <input
      data-slot="input-group-control"
      className={cn(
        "h-full w-full min-w-0 flex-1 bg-transparent text-sm outline-none",
        "placeholder:text-muted-foreground disabled:cursor-not-allowed",
        className
      )}
      {...props}
    />
  );
}

function InputGroupTextarea({ className, ...props }: React.ComponentProps<"textarea">) {
  return (
    <textarea
      data-slot="input-group-control"
      className={cn(
        "field-sizing-content min-h-16 w-full flex-1 resize-none bg-transparent py-2 text-sm outline-none",
        "placeholder:text-muted-foreground disabled:cursor-not-allowed",
        className
      )}
      {...props}
    />
  );
}

function InputGroupText({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="input-group-text"
      className={cn("text-sm text-muted-foreground select-none", className)}
      {...props}
    />
  );
}

export {
  InputGroup,
  InputGroupAddon,
  InputGroupControl,
  InputGroupTextarea,
  InputGroupText,
  inputGroupVariants,
};
